$ErrorActionPreference='Stop';$stamp=Get-Date -Format 'yyyyMMdd-HHmmss'
[pscustomobject]@{Time=(Get-Date).ToString('o');Processes=@(Get-Process | Where-Object {$_.ProcessName -match '^(OpenRGB|lghub|logi)'} | Select-Object Id,ProcessName,Path,StartTime);Services=@(Get-CimInstance Win32_Service -Filter "Name='logi_lamparray_service' OR Name='LGHUBUpdaterService'" | Select-Object Name,State,StartMode,ProcessId);MainSHA256=(Get-FileHash (Join-Path $env:APPDATA 'OpenRGB\Main.orp')).Hash} | ConvertTo-Json -Depth 4 | Set-Content (Join-Path $PSScriptRoot "runtime-$stamp.json") -Encoding UTF8
